export const HERO_CITIES = COUNTRY_SKIES;

const SKY_BY_ISO3 = new Map(COUNTRY_SKIES.map((c) => [c.iso, c]));
const ISO2_TO_ISO3: Record<string, string> = {};
for (const [iso3, iso2] of Object.entries(ISO3_TO_ISO2)) {
  if (SKY_BY_ISO3.has(iso3)) ISO2_TO_ISO3[iso2] = iso3;
}

export function findCityById(idOrIso: string | null | undefined): CountrySky {
  if (!idOrIso) return COUNTRY_SKIES[0];
  const key = idOrIso.trim().toLowerCase();
  return (
    COUNTRY_SKIES.find((c) => c.id === key || c.iso.toLowerCase() === key) ?? COUNTRY_SKIES[0]
  );
}

export function matchCityByTimezone(tz: string | null | undefined): CountrySky | undefined {
  if (!tz) return undefined;
  return COUNTRY_SKIES.find((c) => c.tzPrefixes.some((p) => tz.startsWith(p)));
}

export function matchCityByLocale(langs?: readonly string[] | null): CountrySky | undefined {
  if (!langs || !langs.length) return undefined;
  for (const tag of langs) {
    if (!tag) continue;
    const parts = tag.split(/[-_]/);
    const region = parts.slice(1).find((p) => /^[A-Za-z]{2}$/.test(p))?.toUpperCase();
    if (!region) continue;
    const iso2 = region === 'UK' ? 'GB' : region;
    const iso3 = ISO2_TO_ISO3[iso2];
    if (iso3) {
      const hit = SKY_BY_ISO3.get(iso3);
      if (hit) return hit;
    }
  }
  return undefined;
}

export function detectBrowserCountrySky(): { sky: CountrySky; method: 'tz' | 'locale' | 'default' } {
  if (typeof window === 'undefined') return { sky: COUNTRY_SKIES[0], method: 'default' };
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
    const tzHit = matchCityByTimezone(tz);
    if (tzHit) return { sky: tzHit, method: 'tz' };
    const langs = navigator.languages?.length ? navigator.languages : [navigator.language];
    const locHit = matchCityByLocale(langs);
    if (locHit) return { sky: locHit, method: 'locale' };
  } catch {
    // Keep Coastal Harbour fallback
  }
  return { sky: COUNTRY_SKIES[0], method: 'default' };
}
